def load_rows(paths):
    rows, dup = [], []
    seen = {}
    for path in paths:
        try:
            fh = open(path, encoding="utf-8")
        except OSError as e:
            raise Fail(f"cannot read --runs {path}: {e.strerror}")
        with fh:
            for n, line in enumerate(fh, 1):
                if not line.strip():
                    continue
                where = f"{path}:{n}"
                try:
                    row = json.loads(line)
